173        const args = piAi.validateToolArguments(spec.definition, call) as Record<string, unknown>;
174        const result = await spec.run(args, session, signal, call.id);
175  
176        //M 工具交回一段文字：原样给模型。
177        if (typeof result === 'string') return { text: result, isError: false };
178  
179        //M 工具交回几块：文字拼起来，图片单独挑出来。
180        const text = piAi.contentText(result);
